function createGroundBallMatchSituation(match, legalChoices, classification, opportunity = null) {
  validateHighSchoolReceiverSourceMetadata(match);
  if (!match || typeof MatchSituationLifecycle === "undefined" || !match.groundBallInPlayState?.supported
    || match.defensiveSituation?.familyId !== "infield") return null;
  const handoff = match.groundBallInPlayState;
  assertHighSchoolGroundParticipant(match);
  const situationId = MatchSituationLifecycle.createSituationId({
    gameId: match.id,
    inning: match.inning,
    half: match.half,
    paIdentity: handoff.identity,
    simulationPoint: opportunity?.opportunityId || match.currentMomentId || match.simulationCursor,
    type: MatchSituationLifecycle.TYPES.groundBallDefensiveDecision
  });
  const existing = MatchSituationLifecycle.normalizeSituation(match.activeSituation);
  if (existing?.situationId === situationId) {
    match.activeSituation = existing;
    return existing;
  }
  if (existing && !MatchSituationLifecycle.canResumeSimulation(existing)) return existing;
  const presentationText = getHighSchoolDefensiveSituationText(match);
  let situation = MatchSituationLifecycle.createSituation({
    situationId,
    type: MatchSituationLifecycle.TYPES.groundBallDefensiveDecision,
    actor: {
      id: "player",
      role: match.defensiveSituation.responsibility?.playerRole || "",
      position: match.defensiveSituation.playerPosition || ""
    },
    sourceAuthority: "BattedBallPhysicalTruth+GroundBallRunnerRealization+InfieldRouteAvailability",
    sourcePhysicalStateRef: handoff.identity,
    createdAt: {
      inning: match.inning,
      half: match.half,
      outs: match.outs,
      score: { ...match.scores },
      bases: match.runners.slice(0, 3),
      paIdentity: handoff.identity,
      simulationPoint: opportunity?.opportunityId || match.currentMomentId || match.simulationCursor
    },
    contextSnapshot: {
      familyId: "infield",
      playerPosition: match.defensiveSituation.playerPosition,
      ...(handoff.firstBaseContext ? { firstBaseContext: handoff.firstBaseContext } : {}),
      ballContext: handoff.ballContext,
      physicalIdentity: handoff.physicalTruth?.identity || "",
      ...(handoff.receiverSourcePin ? { receiverSourcePin: handoff.receiverSourcePin } : {}),
      runnerRealization: handoff.runnerRealization,
      forceState: handoff.forceState,
      timingWindows: handoff.timingWindows,
      presentationText
    },
    legalRoutes: legalChoices,
    recommendation: {
      direction: match.coachTacticalDirection ? JSON.parse(JSON.stringify(match.coachTacticalDirection)) : null,
      presentation: match.coachInstruction || ""
    },
    previousSituationSummary: match.lastClosedSituationSummary || null
  });
  situation = MatchSituationLifecycle.admitSituation(situation, {
    supported: true,
    playerOwnsDecision: classification?.eventClassification === "playerMeaningfulDecision",
    reason: classification?.eventClassification === "playerMeaningfulDecision"
      ? "groundBallMultipleMeaningfulRoutes" : "groundBallAutomaticResolution"
  });
  if (situation.admission.admittedToPlayer) situation = MatchSituationLifecycle.presentSituation(situation);
  match.activeSituation = situation;
  return situation;
}

function getHighSchoolYearOneMatchMomentChoices(match = prepareCurrentHighSchoolYearOneMatch()) {
  const activeSituation = typeof MatchSituationLifecycle !== "undefined"
    ? MatchSituationLifecycle.normalizeSituation(match?.activeSituation) : null;
  if (activeSituation?.type === "plateDecision"
    && activeSituation.lifecycleState === "presented") return getHighSchoolPlateDecisionChoices(match);
  if (match?.simulationPhase === "offensive_agency_ready") return getHighSchoolOffensiveAgencyChoices(match);
  const momentId = getHighSchoolYearOneMomentId(match);
  if (!momentId) return [];
  if (match.momentIndex === 1) {
    return getHighSchoolDefensiveMomentChoices(match);
  }
  ensureHighSchoolBatterAnticipationState(match);
  return buildOffensiveDecisionChoices(match).filter(choice => isOffensiveDecisionChoiceLegal(choice, match));
}

function isOffensiveDecisionChoiceLegal(choice, match) {
  if (!choice || choice.executionOnly || match?.currentDomain === "defense") return false;
  const context = analyzeHighSchoolOffensiveDecisionContext(match);
  const runnerObjectives = new Set(["advanceRunner", "scoreRunner", "avoidDoublePlay"]);
  if (!context.hasRunner && runnerObjectives.has(choice.objective)) return false;
  if (context.twoOuts && ["sacrificeAdvance", "sacrificeFly"].includes(choice.objective)) return false;
  if (context.twoOuts && ["sacrificeAdvance", "sacrificeFly"].includes(choice.route)) return false;
  const checks = {
    runnerOnFirst: context.first,
    runnerOnSecond: context.second,
    runnerOnThird: context.third,
    runnerInScoringPosition: context.scoringPosition,
    anyRunner: context.hasRunner,
    fewerThanTwoOuts: !context.twoOuts,
    doublePlayPossible: context.first && !context.twoOuts
  };
  return (choice.requirements || []).every(requirement => checks[requirement] === true);
}

function resolveDefensiveOpportunity({ physicalTruth, activeRoster, topologyVersion = TOPOLOGY_VERSION } = {}) {
  const opportunity = deriveDefensiveOpportunity(physicalTruth, topologyVersion);
  if (!opportunity.supported) return opportunity;
  const assignment = Roster.validateActiveDefense(activeRoster);
  if (!assignment.ok) return freeze({ ...opportunity, supported: false, bindingStatus: "invalid",
    fallbackReason: "invalidActiveAssignment", assignmentIssues: assignment.issues.slice() });
  const primary = Roster.getCurrentDefender(activeRoster, opportunity.primaryPosition);
  const secondaryDefenders = opportunity.secondaryPositions.map(position => ({
    position, defenderId: Roster.getCurrentDefender(activeRoster, position)?.id || ""
  }));
  if (!primary || secondaryDefenders.some(actor => !actor.defenderId)) {
    return freeze({ ...opportunity, supported: false, bindingStatus: "invalid", fallbackReason: "activeDefenderUnavailable" });
  }
  return freeze({ ...opportunity, primaryDefenderId: primary.id, secondaryDefenders, bindingStatus: "bound" });
}

function admitSituation(situation, input = {}) {
  const routes = normalizeRoutes(situation.legalRoutes);
  const meaningfulRouteIds = [...new Set(routes.map(route => route.routeId || route.id || route.matchDecision).filter(Boolean))];
  const supported = input.supported !== false;
  const playerOwnsDecision = input.playerOwnsDecision === true;
  const admittedToPlayer = supported && playerOwnsDecision && meaningfulRouteIds.length >= 2;
  const mode = !supported ? "unsupportedFallback" : admittedToPlayer ? "playerDecision"
    : meaningfulRouteIds.length <= 1 ? "automaticResolution" : "aiDecision";
  const reason = input.reason || (admittedToPlayer ? "multipleBehaviorallyDistinctPlayerRoutes"
    : !supported ? "unsupportedSituation"
      : meaningfulRouteIds.length <= 1 ? "fewerThanTwoMeaningfulRoutes" : "playerDecisionOwnershipDenied");
  return transition(situation, "admitted", {
    admission: { mode, admittedToPlayer, reason, meaningfulRouteCount: meaningfulRouteIds.length }
  }, { reason });
}

function collectCompetitionEvidence(input = {}) {
  const match = input.match || {};
  const exposure = input.exposure || match.gameExposureState || {};
  const readiness = input.readiness || exposure.opportunitySnapshot?.readinessSnapshot || {};
  const contribution = match.playerContribution || {};
  const moments = Array.isArray(match.completedMoments) ? match.completedMoments : [];
  const matchExperience = match.matchExperience || {};
  const matchExperienceSummary = matchExperience.evidenceSummary || {};
  const started = exposure.started === true || exposure.appearanceType === "start";
  const plateAppearances = Math.max(0, Number(exposure.plateAppearances) || 0);
  const defensiveInnings = Math.max(0, Number(exposure.defensiveInnings) || 0);
  const enteredGame = exposure.participated === true || started || plateAppearances > 0 || defensiveInnings > 0;
  const strong = Math.max(0, Number(contribution.strong) || 0);
  const mixed = Math.max(0, Number(contribution.mixed) || 0);
  const failure = Math.max(0, Number(contribution.failure) || 0);
  const errors = Math.max(0, Number(contribution.errors) || 0);
  const performanceSamples = Math.max(strong + mixed + failure, moments.length, Math.min(plateAppearances + Math.min(defensiveInnings, 2), 4));
  const contributionQuality = performanceSamples > 0
    ? ((strong * 2.4) + (mixed * 0.45) - (failure * 2.2) - (errors * 0.8)) / performanceSamples : 0;
  const momentQuality = moments.length
    ? moments.reduce((sum, moment) => sum + getMomentQuality(moment), 0) / moments.length : 0;
  const quality = enteredGame ? clamp((contributionQuality * 1.6) + (momentQuality * 0.55), -5, 5) : 0;
  const sampleConfidence = enteredGame ? clamp(performanceSamples / 3, 0.25, 1) : 0;
  const positionReadiness = clamp(readiness.positionReadiness, 0, 10, 5);
  const positionFit = clamp(readiness.positionFit, 0, 10, 5);
  const coachTrust = clamp(input.coachTrust, 0, 20, 0);
  const health = input.health || {};
  const fatigue = clamp(health.fatigue, 0, 20, 0);
  const injuryRisk = clamp(health.injuryRisk, 0, 20, 0);
  const pain = clamp(health.pain, 0, 20, 0);
  const trainingScore = clamp(
    ((positionReadiness - 5) * 0.7) + ((positionFit - 5) * 0.3) + ((coachTrust - 6) * 0.12)
      - (fatigue * 0.04) - (injuryRisk * 0.08) - (pain * 0.12),
    -3,
    3
  );
  const sampleScore = round((quality * sampleConfidence) + (trainingScore * 0.35));
  return Object.freeze({
    matchIdentity: String(match.id || input.matchIdentity || ""),
    trainingEvidence: Object.freeze({ positionReadiness, positionFit, coachTrust, fatigue, injuryRisk, pain, score: round(trainingScore) }),
    exposureEvidence: Object.freeze({ started, enteredGame, noAppearance: !enteredGame, appearanceType: exposure.appearanceType || (enteredGame ? "appearance" : "noAppearance"), plateAppearances, defensiveInnings }),
    matchEvidence: Object.freeze({
      quality: round(quality), sampleSize: performanceSamples, sampleConfidence: round(sampleConfidence),
      strong, mixed, failure, errors, decisionExecutionSamples: moments.length,
      matchExperienceEvidenceCount: Math.max(0, Number(matchExperienceSummary.total) || 0),
      activeExperienceEvidenceCount: Math.max(0, Number(matchExperienceSummary.active) || 0),
      developmentContextCount: Array.isArray(matchExperience.selectedContexts) ? matchExperience.selectedContexts.length : 0,
      matchExperienceSettlementId: String(matchExperience.matchExperienceSettlementId || "")
    }),
    sampleScore
  });
}

function updateCompetitionEvaluation(saved, evidence, identity = "") {
  const state = normalizeEvaluationState(saved, identity);
  if (!evidence?.matchIdentity) return { status: "invalid", state };
  if (state.appliedMatchIdentities.includes(evidence.matchIdentity)) return { status: "duplicate", state };
  state.evidenceHistory.push(clone(evidence));
  state.evidenceHistory = state.evidenceHistory.slice(-MAX_EVIDENCE_HISTORY);
  state.appliedMatchIdentities.push(evidence.matchIdentity);
  state.appliedMatchIdentities = state.appliedMatchIdentities.slice(-12);
  state.sampleCount = state.evidenceHistory.length;
  state.trainingEvidence = clone(evidence.trainingEvidence);
  state.matchEvidence = clone(evidence.matchEvidence);
  state.exposureEvidence = clone(evidence.exposureEvidence);
  const weighted = state.evidenceHistory.map((item, index, all) => ({ value: Number(item.sampleScore) || 0, weight: index + 1 + Math.max(0, 3 - all.length) }));
  const totalWeight = weighted.reduce((sum, item) => sum + item.weight, 0) || 1;
  state.accumulatedScore = round(weighted.reduce((sum, item) => sum + item.value * item.weight, 0) / totalWeight);
  const recent = state.evidenceHistory.slice(-2);
  state.trendScore = round(recent.reduce((sum, item) => sum + (Number(item.sampleScore) || 0), 0) / Math.max(1, recent.length));
  state.recentTrend = state.trendScore >= 1 ? "positive" : state.trendScore <= -1 ? "negative" : "neutral";
  state.promotionPressure = round(clamp(state.accumulatedScore, 0, 5));
  state.demotionPressure = round(clamp(-state.accumulatedScore, 0, 5));
  state.rolePressure = state.promotionPressure >= 1.4 ? "promotion" : state.demotionPressure >= 1.4 ? "demotion" : "stable";
  return { status: "applied", state };
}

function settleMatchExperienceDevelopment(target, match, options = {}) {
  if (!enabled || options.enabled === false) return deepFreeze({ ok: true, status: "disabled", settled: false, contexts: [] });
  if (!target || !match || match.completed !== true) return deepFreeze({ ok: false, status: "rejected", errors: ["completed-match-required"] });
  const existing = normalizeMatchExperienceState(match.matchExperience, match);
  if (existing?.settled) return deepFreeze({ ok: true, status: "duplicate", duplicate: true, settled: true, state: clone(existing) });
  const state = existing || createMatchExperienceState(match);
  const exposure = options.exposure || derivePlayerExposure(match);
  const evidence = deriveMatchExperienceEvidence(match, { ...options, exposure });
  const aggregated = aggregateMatchExperience(evidence);
  const contexts = selectDevelopmentContexts(aggregated, match, "player");
  const applications = [];
  const errors = [];
  contexts.forEach(context => {
    const application = typeof applyDevelopmentResult === "function"
      ? applyDevelopmentResult(target, { ...context, metadata: { ...context.metadata, settlementId: context.settlementId } })
      : { ok: false, status: "rejected", errors: ["development-processor-unavailable"] };
    if (!application.ok) errors.push(...(application.errors || [application.status || "development-application-failed"]));
    applications.push(application);
  });
  state.finalized = true;
  state.settled = errors.length === 0;
  state.matchExperienceSettlementId = `${match.id || "match"}|${Math.max(0, Number(match.simulationSeed) || 0)}|player|${VERSION}`;
  state.exposure = {
    defensiveInnings: exposure.defensiveInnings,
    plateAppearances: exposure.plateAppearances,
    defensiveExposureValue: getDefensiveInningsExposureValue(exposure.defensiveInnings),
    plateAppearanceExposureValue: getPlateAppearanceExposureValue(exposure.plateAppearances)
  };
  state.evidence = evidence.slice(-MAX_EVIDENCE_RECORDS).map(clone);
  state.evidenceSummary = {
    total: evidence.length,
    exposure: evidence.filter(item => item.evidenceType === "exposure").length,
    active: evidence.filter(item => item.evidenceType === "active").length,
    noveltyGroups: new Set(evidence.map(item => item.novelty.semanticKey)).size
  };
  state.aggregated = aggregated.map(clone);
  state.selectedContexts = contexts.map(clone);
  state.developmentSettlementIds = contexts.map(context => context.settlementId);
  state.developmentResults = applications.map(application => clone(application.result || { status: application.status }));
  state.errors = errors.slice(0, 10);
  match.matchExperience = state;
  return deepFreeze({ ok: errors.length === 0, status: errors.length ? "rejected" : "applied", duplicate: false, settled: state.settled, contexts: clone(contexts), applications: clone(applications), state: clone(state) });
}

function completeHighSchoolEntry(options = {}) {
  const state = player?.schoolInvitationState;
  const invitationValidation = validateSchoolInvitationSet(state);
  if (!invitationValidation.ok) {
    showNotice("高中邀請資料不完整，暫時不能進入高中主篇。", "error");
    return false;
  }
  const directStartBypass = state.compatibilityMode === "direct-start-bypass";
  if (!directStartBypass && state.selectionFinalized !== true) {
    showNotice("請先確認一間高中，再進入高中主篇。", "warning");
    return false;
  }
  if (!directStartBypass && !state.selectedSchoolRoster) {
    materializeSelectedHighSchoolRoster(player, { rosterRole: "bench" });
  }
  if (player.chapter === "青棒" && Number(player.age) === 16) return true;
  const schoolContext = getSelectedHighSchoolContext(player);
  applyChapterBreather();
  player.chapter = "青棒";
  player.age = 16;
  player.highSchoolStep = 0;
  player.highSchoolPositionPreference = player.primaryPosition || "";
  player.highSchoolRoleCode = "";
  player.highSchoolCompetitionEvaluation = null;
  player.highSchoolOpportunityHistory = [];
  player.highSchoolNextOpportunity = null;
  player.highSchoolYearOneStartingRole = "";
  player.highSchoolYearOneMatchHistory = [];
  player.highSchoolYearOneComplete = false;
  player.highSchoolMatch = createInitialPlayer().highSchoolMatch;
  player.highSchoolAzheEcho = createInitialPlayer().highSchoolAzheEcho;
  player.highSchoolRivalContext = createInitialPlayer().highSchoolRivalContext;
  const schoolName = schoolContext?.schoolName || state.legacyExistingSchool?.schoolName || player.highSchoolRoute;
  showNotice(`你進入${schoolName}，高中棒球正式開始。`, "success");
  showCurrentEvent();
  return true;
}

function toMatchRoster(teamRoster, strengthProfile = null) {
  const byId = new Map(teamRoster.players.map(player => [player.playerId, player]));
  const lineup = teamRoster.battingOrder.map(slot => {
    const player = byId.get(slot.playerId);
    return Object.freeze({ ...player, id: player.id || player.playerId, position: POSITION_LABELS[slot.defensivePosition], defensivePosition: slot.defensivePosition, source: player.id === "player" ? "canonical-player" : "simulation-roster" });
  });
  const starterIds = new Set(lineup.map(player => player.playerId));
  const bench = teamRoster.benchPlayers.filter(player => !starterIds.has(player.playerId)).map(player => Object.freeze({ ...player, id: player.id || player.playerId, position: POSITION_LABELS[player.primaryPosition], source: player.id === "player" ? "canonical-player" : "simulation-roster" }));
  const roster = { lineup, bench, pitchingStaff: teamRoster.pitchingStaff, teamRoster, teamStrengthProfile: strengthProfile, source: VERSION };
  assertActiveDefense(roster);
  return roster;
}

function injectPlayerIntoRoster(baseRoster, playerActor, options = {}) {
  if (!validateRoster(baseRoster).ok) throw new Error("Player injection requires a valid base TeamRoster.");
  const actor = createPlayerActor(playerActor, baseRoster.teamId);
  const requestedPosition = normalizePosition(options.playerPosition || actor.primaryPosition);
  const starterRequested = options.playerRole === "starter";
  const starterAllowed = starterRequested && requestedPosition && isPositionEligible(actor, requestedPosition);
  const starters = baseRoster.starters.filter(player => player.id !== "player").slice();
  const benchPlayers = baseRoster.benchPlayers.filter(player => player.id !== "player").slice();
  let replacedPlayerId = "";
  if (starterAllowed) {
    const assignedStarterId = baseRoster.battingOrder?.find(slot => slot.defensivePosition === requestedPosition)?.playerId;
    const index = starters.findIndex(player => player.playerId === assignedStarterId);
    if (index >= 0) {
      const incumbent = starters[index];
      replacedPlayerId = incumbent.playerId;
      benchPlayers.push(incumbent);
      starters[index] = Object.freeze({ ...actor, primaryPosition: requestedPosition });
    } else benchPlayers.push(actor);
  } else benchPlayers.push(actor);
  const player = starters.find(item => item.id === "player") || benchPlayers.find(item => item.id === "player");
  const existingIds = new Set([...starters, ...benchPlayers].map(item => item.playerId));
  const players = [...baseRoster.players.filter(item => item.id !== "player" && existingIds.has(item.playerId)), player].filter(Boolean);
  const battingOrder = orderLineup(starters);
  const pitchingStaff = requestedPosition === "P" && starterAllowed && replacedPlayerId
    ? Object.freeze({ starter: player.playerId, secondaryPitchers: Object.freeze([replacedPlayerId, ...(baseRoster.pitchingStaff?.secondaryPitchers || []).filter(id => id !== replacedPlayerId)]) })
    : baseRoster.pitchingStaff;
  return Object.freeze({
    ...baseRoster,
    players: Object.freeze(players), starters: Object.freeze(starters), benchPlayers: Object.freeze(benchPlayers), battingOrder, pitchingStaff,
    playerInjection: Object.freeze({
      playerId: player?.playerId || "player", requestedPosition, assignedPosition: starterAllowed && replacedPlayerId ? requestedPosition : "",
      rosterRole: starterAllowed && replacedPlayerId ? "starter" : "bench", replacedPlayerId,
      legal: requestedPosition ? isHighSchoolPositionAssignmentLegal(actor, requestedPosition) : false
    })
  });
}

function resolvePlannedAppearance(score, role, coachStyle, hash) {
  if (score >= 55) return { appearanceType: "start", entryInning: 1, entryHalf: "上" };
  if (score < 36) return { appearanceType: "noAppearance", entryInning: null, entryHalf: "" };
  const entryInning = role === "rotation" ? 5 : 5 + (hash % 2);
  const appearanceSelector = hash % 10;
  const appearanceType = coachStyle === "developmental" || appearanceSelector <= 3
    ? "defensiveSubstitution"
    : appearanceSelector <= 6 ? "pinchHit" : "lateGameAppearance";
  return { appearanceType, entryInning, entryHalf: "下" };
}

function markSettled(situation, input = {}) {
  if (situation.lifecycleState === "settled" || situation.lifecycleState === "closed") return situation;
  return transition(situation, "settled", {
    settlement: { applied: true, identity: input.identity || `${situation.situationId}|settlement` }
  }, { phase: situation.phase, reason: "canonicalSettlementApplied" });
}

function closeSituation(situation, input = {}) {
  if (situation.lifecycleState === "closed") return situation;
  if (!situation.resolution || situation.settlement?.applied !== true
    || situation.reassessmentState?.requiresDecision === true || situation.executionState?.status === "inProgress") {
    throw new Error("match situation cannot close before resolution and settlement");
  }
  return transition(situation, "closed", {
    closeState: { reason: input.reason || "settlementComplete", readyToResume: true }
  }, { phase: situation.phase, reason: input.reason || "settlementComplete" });
}

function evaluateHighSchoolMatchDefensiveDecisionDensity(match, situation, legalChoices = [], classification = null) {
  const state = ensureHighSchoolMatchDecisionDensityState(match);
  const descriptor = createHighSchoolDefensiveNoveltyDescriptor(situation, legalChoices);
  const playIndex = Array.isArray(match?.simulationLog) ? match.simulationLog.length : 0;
  const spacing = state?.lastDecisionPlayIndex >= 0 ? playIndex - state.lastDecisionPlayIndex : Number.POSITIVE_INFINITY;
  const meaningfulCandidate = classification?.eventClassification === "playerMeaningfulDecision";
  const repeated = meaningfulCandidate && descriptor.noveltyKey === state?.lastNoveltyKey;
  const situationNovel = meaningfulCandidate && !state?.recentSituationFamilies.includes(descriptor.situationFamily);
  const routeNovel = meaningfulCandidate && !state?.recentRouteFamilies.includes(descriptor.routeFamily);
  let allowed = meaningfulCandidate;
  let suppressionReason = "";
  if (!meaningfulCandidate) {
    allowed = false;
    suppressionReason = "not-meaningful";
  } else if ((state?.defensiveMeaningfulDecisionCount || 0) >= 4 && !routeNovel) {
    allowed = false;
    suppressionReason = "route-family-density";
  } else if (repeated && spacing < MATCH_DECISION_REPEAT_SPACING) {
    allowed = false;
    suppressionReason = "repeated-situation-spacing";
  } else if ((state?.currentConsecutiveMeaningfulDecisions || 0) >= MATCH_DECISION_MAX_CONSECUTIVE && spacing <= 1) {
    allowed = false;
    suppressionReason = "decision-density-spacing";
  } else if ((state?.defensiveMeaningfulDecisionCount || 0) >= MATCH_DECISION_ABSOLUTE_SAFETY_CAP) {
    allowed = false;
    suppressionReason = "absolute-safety-cap";
  }
  return Object.freeze({
    version: MATCH_DECISION_DENSITY_VERSION,
    allowed,
    meaningfulCandidate,
    suppressionReason,
    playIndex,
    spacing: Number.isFinite(spacing) ? spacing : null,
    repeated,
    situationNovel,
    routeNovel,
    highNovelty: situationNovel || routeNovel,
    absoluteSafetyCap: MATCH_DECISION_ABSOLUTE_SAFETY_CAP,
    maxConsecutiveMeaningfulDecisions: MATCH_DECISION_MAX_CONSECUTIVE,
    ...descriptor
  });
}

