function getOffensiveSimulationCapability(subject = player) {
  if (subject?.id === "player") subject = player;
  if (["simulation-roster", "team-roster-foundation"].includes(subject?.source)) {
    return Object.freeze({ contact: subject.contact, power: subject.power, speed: subject.speed, discipline: Math.round((subject.contact + subject.speed) / 2) });
  }
  const skills = subject.baseballSkills || {};
  return Object.freeze({
    contact: Math.round(((Number(skills.batting) || 0) * 2 + (Number(subject.ballSense) || 0) + (Number(subject.observe) || 0)) / 4),
    power: Math.round(((Number(skills.batting) || 0) + (Number(subject.fitness) || 0) + (Number(subject.instinct) || 0)) / 3),
    speed: Math.round(((Number(skills.baseRunning) || 0) * 2 + (Number(subject.fitness) || 0)) / 3),
    discipline: Math.round(((Number(skills.baseballIQ) || 0) + (Number(subject.observe) || 0) + (Number(subject.discipline) || 0)) / 3)
  });
}

function getDefensiveSimulationCapability(subject = player, position = player.primaryPosition, matchContext = subject?.highSchoolMatch) {
  if (["simulation-roster", "team-roster-foundation"].includes(subject?.source)) {
    return Object.freeze({ fielding: subject.defense, reaction: subject.defense, range: subject.defense, arm: subject.arm, throwing: subject.arm, decision: Math.round((subject.defense + subject.contact) / 2) });
  }
  const rawSkills = subject.baseballSkills || {};
  const activeMatch = matchContext || (subject === player ? player.highSchoolMatch : null);
  const audit = getDevelopmentMatchPositionTestCapabilityAudit(subject, activeMatch);
  const skills = audit.active && !activeMatch?.completed
    ? Object.fromEntries(Object.keys(rawSkills).map(skill => [skill, audit.skills[skill]?.effective ?? rawSkills[skill]]))
    : rawSkills;
  const effectivePosition = audit.active ? audit.position : position;
  const positionTools = {
    "內野手": ["catching", "reaction", "throwing"],
    "外野手": ["catching", "range", "armStrength"],
    "捕手": ["blocking", "gameCalling", "throwing"],
    "投手": ["control", "reaction", "throwing"]
  }[position] || ["catching", "reaction", "throwing"];
  const values = positionTools.map(key => Number(skills[key]) || 0);
  const reactionSkill = Number(skills.reaction) || values[1] || 0;
  const throwingSkill = values[2] || 0;
  const armSkill = ["游擊手", "三壘手"].includes(effectivePosition) ? Number(skills.armStrength) || throwingSkill : throwingSkill;
  return Object.freeze({
    fielding: Math.round((values[0] * 2 + values[1] + (Number(subject.ballSense) || 0)) / 4),
    reaction: Math.round((reactionSkill * 2 + (Number(subject.ballSense) || 0)) / 3),
    range: Math.round(((Number(skills.range) || reactionSkill) * 2 + (Number(subject.fitness) || 0)) / 3),
    arm: Math.round((armSkill * 2 + (Number(subject.fitness) || 0)) / 3),
    throwing: Math.round((throwingSkill * 2 + (Number(subject.observe) || 0)) / 3),
    decision: Math.round(((Number(skills.baseballIQ) || 0) + (Number(subject.observe) || 0) + (Number(subject.discipline) || 0)) / 3)
  });
}

function assertHighSchoolMatchCapabilityAdmission(subject = player) {
  const validation = validateHighSchoolEntryCapability(subject);
  if (!validation.ok) {
    throw new Error(`正式高中比賽拒絕未完成 Capability Settlement 的球員：${validation.errors.join(",")}`);
  }
  return true;
}

function recordGroundBallSituationResolution(match, resolution) {
  if (!match || !resolution || typeof MatchSituationLifecycle === "undefined") return null;
  let situation = MatchSituationLifecycle.normalizeSituation(match.activeSituation);
  if (!situation || situation.type !== MatchSituationLifecycle.TYPES.groundBallDefensiveDecision
    || situation.lifecycleState !== "executing") return situation;
  validateHighSchoolDecisionThrowState(match);
  const handoff = match.groundBallInPlayState;
  if (handoff?.firstBaseExecution && Object.entries(handoff.firstBaseExecution.resolution)
    .some(([key, value]) => JSON.stringify(resolution[key]) !== JSON.stringify(value))) throw new Error("Stale first-base settlement execution facts");
  if (handoff?.thirdBaseExecution && Object.entries(handoff.thirdBaseExecution.resolution)
    .some(([key, value]) => JSON.stringify(resolution[key]) !== JSON.stringify(value))) throw new Error("Stale 3B settlement execution facts");
  if (handoff?.shortstopExecution && Object.entries(handoff.shortstopExecution.resolution)
    .some(([key, value]) => JSON.stringify(resolution[key]) !== JSON.stringify(value))) throw new Error("Stale SS settlement execution facts");
  if (handoff?.supported && !handoff.settlementApplied && !handoff.secureResolution
    && handoff.defensiveAccess?.reachResolution && resolution.playerLeg?.control
    && typeof DefensiveReachSecureFoundation !== "undefined") {
    assertHighSchoolDetailedResponsibility(match, handoff.physicalTruth, "2B", "player");
    const securedHandoff = BattedBallGroundDefense.normalizeHandoff({ ...handoff,
      secureResolution: DefensiveReachSecureFoundation.projectGroundControl(handoff.defensiveAccess.reachResolution, resolution.playerLeg.control, resolution.controlEvidence) });
    const decisionThrowState = projectHighSchoolControlledDecisionThrow(match, resolution, securedHandoff);
    match.groundBallInPlayState = BattedBallGroundDefense.normalizeHandoff({ ...securedHandoff, ...(decisionThrowState ? { decisionThrowState } : {}) });
    if (decisionThrowState && typeof DefensiveRunnerThrowSettlementFoundation !== "undefined") {
      const route = decisionThrowState.activeSelection?.route || decisionThrowState.selection?.route;
      const receiverFact = route?.routeId === "initiate463" ? resolution.teammateLeg?.shortstopReceive
        : route?.routeId === "preventRunHome" && !resolution.reassessed ? resolution.teammateLeg?.catcherReceive : resolution.teammateLeg?.receiver;
      const runnerThrowTiming = DefensiveRunnerThrowSettlementFoundation.projectExistingTiming({ stage: decisionThrowState,
        runnerState: handoff.runnerPhysicalStates?.find(r => r.runnerId === route?.targetRunnerId),
        windowState: resolution.firstLegTimingWindow?.state || "expired", receiverFact: receiverFact || "unavailable",
        tagFact: resolution.homeTagLeg?.arrivalComparison || null });
      match.groundBallInPlayState = BattedBallGroundDefense.normalizeHandoff({ ...match.groundBallInPlayState, runnerThrowTiming });
    }
  }
  if (resolution.reassessment) {
    const remaining = (resolution.reassessment.availableRouteIds || []).map(routeId => ({ routeId }));
    situation = MatchSituationLifecycle.beginReassessment(situation, {
      trigger: resolution.reassessment.reason,
      updatedPhysicalState: {
        firstLegState: resolution.firstLegState || null,
        continuationState: resolution.continuationState || null,
        forceState: resolution.reassessment.forceState || null
      },
      remainingLegalRoutes: remaining,
      requiresDecision: false,
      firstLegApplied: resolution.firstLegState?.status === "completed"
    });
  }
  situation = MatchSituationLifecycle.resolveSituation(situation, {
    physicalOutcomeRef: `${situation.situationId}|physical-resolution`,
    outsDelta: resolution.outsCreated,
    runsDelta: resolution.runsAllowed,
    runnerActorOutcomes: resolution.runnerChanges,
    executionEvidence: match.groundBallInPlayState?.runnerThrowTiming || match.groundBallInPlayState?.shortstopExecution ? resolution : null,
    reason: resolution.reassessment ? "postExecutionReassessmentComplete" : "groundBallExecutionComplete"
  });
  match.activeSituation = situation;
  return situation;
}

function applyInfieldResolutionToHighSchoolMatch(match, decision, resolution) {
  const situation = match.defensiveSituation;
  const groundBallContext = situation?.groundBallDefensiveContext;
  if (resolution.runnerSettlementIdentity && match.lastDefensiveResolution?.runnerSettlementIdentity === resolution.runnerSettlementIdentity) return match.completedMoments.at(-1) || null;
  if (resolution.runnerSettlementIdentity && resolution.runnerSettlementIdentity !== situation?.runnerSettlementIdentity) throw new Error("Stale infield play identity");
  if (groundBallContext && match.groundBallInPlayState?.settlementApplied) return match.completedMoments.at(-1) || null;
  validateHighSchoolDecisionThrowState(match);
  beginGroundBallSituationDecision(match, decision);
  recordGroundBallSituationResolution(match, resolution);
  validateHighSchoolStoredDefensiveResolution(match, resolution);
  const situationBefore = { inning: match.inning, half: match.half, outs: match.outs, scores: { ...match.scores }, runners: match.runners.slice() };
  const presentation = infieldDecisionFamily.present(situation, resolution, decision);
  const explanation = resolution.defensiveOutcomeExplanation || createDefensiveOutcomeExplanation(situation, getInfieldDecisionChoice(situation, match, decision), resolution);
  const thirdOutResolution = finalizeHighSchoolDefensiveThirdOut(match, situationBefore, resolution);
  const runnerChanges = normalizeHighSchoolTerminalRunnerChanges(resolution, thirdOutResolution);
  if (match.groundBallInPlayState?.runnerThrowTiming && typeof DefensiveRunnerThrowSettlementFoundation !== "undefined") {
    const handoff = match.groundBallInPlayState;
    const settlement = DefensiveRunnerThrowSettlementFoundation.projectExistingSettlement({ timing: handoff.runnerThrowTiming,
      stage: handoff.decisionThrowState, before: situationBefore, resolution, thirdOut: thirdOutResolution });
    const applied = applyHighSchoolDefensiveSettlementFacts(match, settlement, "infield-decision-family");
    match.groundBallInPlayState = BattedBallGroundDefense.normalizeHandoff({ ...handoff, playSettlement: applied });
  } else {
    const settlement = DefensiveRunnerThrowSettlementFoundation.projectInfieldSettlement({
      identity: situation.runnerSettlementIdentity, before: situationBefore, resolution, thirdOut: thirdOutResolution });
    applyHighSchoolDefensiveSettlementFacts(match, settlement, "infield-decision-family");
  }
  resolution = projectHighSchoolInfieldScoredResolution(match, situation, resolution);
  if (resolution.error) match.playerContribution.errors += 1;
  match.playerContribution.outsCreated += resolution.outsCreated;
  syncHighSchoolMatchPlayerRunnerLocation(match);
  const situationAfter = { inning: match.inning, half: match.half, outs: match.outs, scores: { ...match.scores }, runners: match.runners.slice() };
  const consequence = resolution.route === "doublePlay" && resolution.outsCreated === 1
    ? `${resolution.causeExplanation} 合理的雙殺判斷只完成一半。` : resolution.causeExplanation;
  const provisionalResolution = {
    ...resolution,
    runnerChanges,
    runnersAfter: thirdOutResolution.basesAfter,
    scoringRunnerIds: thirdOutResolution.legalScoringRunnerIds,
    runsAllowed: thirdOutResolution.legalScoringRunnerIds.length,
    thirdOutResolution
  };
  // Player error attribution stays separate from the team's official PA result.
  const thirdBaseTeamError = resolution.scorerFacts ? resolution.scorerFacts.batterReachedOnError
    : (resolution.thirdBaseEvidence || resolution.firstBaseEvidence) && resolution.actionFacts.actions
      .some(action => action.errorCharged === true && action.status === "failed");

fresh.highSchoolMatch = Object.assign({}, highSchoolDefaults.highSchoolMatch, saved.highSchoolMatch || {});
fresh.highSchoolMatch.scores = Object.assign({}, highSchoolDefaults.highSchoolMatch.scores, saved.highSchoolMatch?.scores || {});
fresh.highSchoolMatch.runners = Array.isArray(saved.highSchoolMatch?.runners) ? saved.highSchoolMatch.runners : [];
fresh.highSchoolMatch.completedMoments = Array.isArray(saved.highSchoolMatch?.completedMoments)
